/**
 * Telegram outbox message for ONE confirmed order.
 *
 * Every order is independent: the message contains exactly one order number,
 * one product and one offer. All values come from the DB/order snapshot —
 * nothing here is generated by the model.
 */

export interface OrderTelegramInput {
  orderNumber: string;
  /** Order creation time (UTC) — formatted in the workspace timezone. */
  createdAt: Date;
  timeZone: string;
  customerName: string | null;
  phone: string | null;
  address: string | null;
  productName: string;
  offerName: string | null;
  /** Final order total for this product (DB pricing engine). */
  price: string | number;
  quantity: number;
  /** Batch delivery share for this order (0 for free delivery). */
  deliveryFee?: string | number | null;
  /** Order total = product subtotal + delivery share. */
  total?: string | number | null;
}

/** `YYYY-MM-DD HH:mm:ss` in the given IANA timezone (24h, stable). */
export function formatOrderDate(date: Date, timeZone: string): string {
  const parts = new Intl.DateTimeFormat("en-CA", {
    timeZone: timeZone || "UTC",
    year: "numeric",
    month: "2-digit",
    day: "2-digit",
    hour: "2-digit",
    minute: "2-digit",
    second: "2-digit",
    hourCycle: "h23",
  }).formatToParts(date);
  const get = (type: string) => parts.find((p) => p.type === type)?.value ?? "00";
  return `${get("year")}-${get("month")}-${get("day")} ${get("hour")}:${get("minute")}:${get("second")}`;
}

/** Plain text (no HTML) — the exact operational format requested by the owner. */
export function buildOrderTelegramMessage(input: OrderTelegramInput): string {
  const lines = [
    `رقم الطلب: ${input.orderNumber}`,
    `تاريخ الطلب: ${formatOrderDate(input.createdAt, input.timeZone)}`,
    `إسم العميل: ${input.customerName?.trim() || "-"}`,
    `رقم الهاتف: ${input.phone?.trim() || "-"}`,
    `عنوان العميل: ${input.address?.trim() || "-"}`,
    `إسم المنتج: ${input.productName}`,
    `إسم العرض: ${input.offerName?.trim() || "-"}`,
    `السعر: ${input.price}`,
    `الكمية: ${input.quantity}`,
  ];
  const deliveryFee = Number(input.deliveryFee ?? 0);
  if (Number.isFinite(deliveryFee) && deliveryFee > 0) {
    lines.push(`رسوم التوصيل: ${input.deliveryFee}`);
    if (input.total !== undefined && input.total !== null) lines.push(`الإجمالي: ${input.total}`);
  }
  return lines.join("\n");
}
